// process_request. client is the format the session's earlier requests
// selected, sha1 until one sends the capability: serve.c keeps it for the
// whole session rather than per request. Each object-format line must name a
// known format, and the last one becomes the session's, which must equal the
// repository's. v2ObjectFormatError returns the session's format after req,
// and an error if req is to be refused. An unknown value is echoed through
// escapeClientValue; a mismatched one is already known to be sha1 or sha256.
func v2ObjectFormatError(repo, client config.ObjectFormat, caps capability.List) (config.ObjectFormat, *pktline.ErrorLine) {
	if caps.Supports(capability.ObjectFormat) {
		vals := caps.Get(capability.ObjectFormat)
		if len(vals) == 0 {
			return client, &pktline.ErrorLine{Text: "object-format capability requires an argument"}
		}
		for _, v := range vals {
			switch config.ObjectFormat(v) {
			case config.SHA1, config.SHA256:
			default:
				return client, &pktline.ErrorLine{Text: fmt.Sprintf("unknown object format '%s'", escapeClientValue(v))}
			}
		}
		client = config.ObjectFormat(vals[len(vals)-1])
	}
	if client != repo {
		return client, &pktline.ErrorLine{Text: fmt.Sprintf("mismatched object format: server %s; client %s", repo, client)}
	}
	return client, nil
}

// rejectWithErrorLine sends e to the client as an ERR packet and returns it.
func rejectWithErrorLine(w io.Writer, e *pktline.ErrorLine) error {
	if err := e.Encode(w); err != nil {
		return errors.Join(e, err)
	}
	return e
}

// rejectReceivePack sends e to a receive-pack client and returns it. A client
// that asked for side-band-64k or side-band demultiplexes the response, so e
// goes on the error band followed by a flush, as git's packet_writer_error
// sends a fatal error to a side-band client; any other client gets an ERR
// packet.
func rejectReceivePack(w io.Writer, caps capability.List, e *pktline.ErrorLine) error {
	var mux *sideband.Muxer
	switch {
	case caps.Supports(capability.Sideband64k):
		mux = sideband.NewMuxer(sideband.Sideband64k, w)
	case caps.Supports(capability.Sideband):
		mux = sideband.NewMuxer(sideband.Sideband, w)
	default:
		return rejectWithErrorLine(w, e)
	}
	if _, err := mux.WriteChannel(sideband.ErrorMessage, []byte(e.Text)); err != nil {
		return errors.Join(e, err)
	}
	if err := pktline.WriteFlush(w); err != nil {
		return errors.Join(e, err)
	}
	return e
}
